import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import { SearchIcon, AnalyticsIcon } from './components/Icons';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';
import type { Chat } from '@google/genai';

const ELITE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 180-Alpha DEEP THINKING Engine. Your objective is to achieve >80% predictive accuracy through adversarial reasoning.

VISION CAPABILITY:
When provided with an image (screenshot of prop bets):
1. EXTRACT: Identify the Player, Stat Category, and Line Value.
2. VALIDATE: Use Google Search to find the current game context for these players.
3. ADVERSARIAL ANALYSIS: For each identified prop, run the Veto Phase simulation.
4. VERDICT: Return a structured analysis for the prop(s) found in the image.

CORE LOGIC - THE TRIPLE-SCRUTINY METHOD:
1. PHASE 1 (QUANT): Analyze Poisson distribution of historical scoring, individual player efficiency deltas (PER), and travel fatigue metrics.
2. PHASE 2 (MARKET): Scrub Google Search for "Sharp Money" movement. Look for line-steaming where the public is heavy on one side but the line moves the other way.
3. PHASE 3 (THE VETO): Act as an antagonist. Search for trap variables (Referee bias, specific defensive clamps, late-breaking rumors).

OUTPUT RULES:
- If an image is provided, focus primarily on the contents of that image.
- MUST return JSON strictly conforming to predictionSchema if a full simulation is requested.
- Tone: Clinical, Quant-focused.`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [teamA, setTeamA] = useState('');
  const [teamB, setTeamB] = useState('');
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setTeamA('');
    setTeamB('');
  }, []);

  useEffect(() => {
    clearSelection();
  }, [selectedSport, clearSelection]);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    setVault(prev => [entry, ...prev.filter(v => v.id !== entry.id)].slice(0, 4));
  }, []);

  const handleSendMessage = useCallback(async (text: string, imageData?: { data: string, mimeType: string }) => {
    if (!text.trim() && !imageData) return;

    setMessages(prev => [...prev, { role: 'user', content: text, imageData: imageData?.data }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const contents: any[] = [];
        if (imageData) {
            contents.push({
                inlineData: {
                    data: imageData.data,
                    mimeType: imageData.mimeType
                }
            });
        }
        contents.push({ text: text || "Analyze this sports screenshot and provide 180-Alpha predictions for the props shown." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: ELITE_SYSTEM_INSTRUCTION,
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Data stream interrupted.";

        try {
            // Attempt to find JSON in the response if it's mixed with text
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine sync lost. Vision analysis buffer exceeded." }]);
    } finally {
        setIsReplying(false);
    }
  }, []);

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || selectedGame?.homeTeam;
    const away = customTeams?.away || selectedGame?.awayTeam;

    if (!home || !away) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const config: any = {
        systemInstruction: ELITE_SYSTEM_INSTRUCTION,
        responseSchema: predictionSchema,
        responseMimeType: 'application/json',
        thinkingConfig: { thinkingBudget: 32768 }
      };

      if (!isRetry) config.tools = [{ googleSearch: {} }];

      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `PERFORM ADVERSARIAL SIMULATION: ${home} vs ${away}. Exhaustively check for trap variables and market delta. Is this an 80% lock? Prove it.`,
        config 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setShowSuggestions(true);
    } catch (err: any) {
      setError("Satellite link timeout. Adversarial analysis scrub failed.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && <div className="bg-red-900/20 border border-red-500/50 text-red-200 px-6 py-4 rounded-2xl mb-6 backdrop-blur-md flex items-center gap-3">
                    <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
                    {error}
                </div>}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12">
                        <div className="bg-zinc-950/40 border border-zinc-900/50 p-8 rounded-[3.5rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity">
                                <AnalyticsIcon className="w-64 h-64 text-white" />
                            </div>
                            <div className="relative z-10 text-center space-y-4 mb-10">
                                <h2 className="text-4xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-amber-100 to-amber-600">
                                    Alpha Command Hub
                                </h2>
                                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600">
                                    Analyze Props • Market Efficiency • Adversarial Scrutiny
                                </p>
                            </div>
                            <form onSubmit={onPromptSubmit} className="relative z-10 max-w-2xl mx-auto">
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Evaluate Suns vs Lakers through Veto Phase..."
                                        className="w-full bg-black/80 border-2 border-zinc-800 rounded-[2rem] px-8 py-6 text-white focus:outline-none focus:border-amber-500/40 transition-all pr-20 text-sm placeholder:text-zinc-700 shadow-[inset_0_2px_20px_rgba(0,0,0,0.5)]"
                                    />
                                    <button type="submit" className="absolute right-4 top-4 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 transition-all hover:scale-105 shadow-[0_0_20px_rgba(245,158,11,0.3)]">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </form>
                        </div>

                        <div className="space-y-6">
                            <div className="text-center">
                                <h3 className="text-[10px] font-black text-zinc-700 uppercase tracking-[0.6em] mb-10">Manual Alpha Override</h3>
                                <TeamSelector teamA={teamA} setTeamA={setTeamA} teamB={teamB} setTeamB={setTeamB} />
                                {teamA && teamB && (
                                    <button 
                                        onClick={() => handlePredict(false, { home: teamA, away: teamB })}
                                        className="mt-10 bg-zinc-900/50 border border-zinc-800/80 px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest text-zinc-400 hover:text-amber-500 hover:border-amber-500/50 transition-all flex items-center gap-3 mx-auto backdrop-blur-xl group"
                                    >
                                        <AnalyticsIcon className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                                        Initialize 180-Alpha Scrutiny
                                    </button>
                                )}
                            </div>
                        </div>

                        <div className="flex flex-col items-center gap-6">
                            <div className="h-px w-32 bg-gradient-to-r from-transparent via-zinc-800 to-transparent"></div>
                            <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        </div>

                        <div className="space-y-6">
                            <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                        </div>

                        {selectedGame && (
                            <div className="fixed bottom-12 left-0 right-0 p-4 flex justify-center z-20 animate-slide-up">
                                <button onClick={() => handlePredict()} className="bg-gradient-to-br from-amber-400 to-orange-600 text-black font-black text-xl py-6 px-20 rounded-full shadow-[0_10px_60px_rgba(245,158,11,0.4)] hover:shadow-[0_10px_80px_rgba(245,158,11,0.6)] transform hover:scale-105 transition-all flex items-center gap-4 border-t-2 border-white/20">
                                    <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                                    SCRUTINIZE {selectedGame.homeTeam.toUpperCase()} MATCHUP
                                </button>
                            </div>
                        )}
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center px-2">
                            <button onClick={clearSelection} className="text-zinc-600 hover:text-white text-[10px] font-black uppercase tracking-widest flex items-center gap-2 transition-colors">
                                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                                Release Signal Stream
                            </button>
                            <div className="flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                                <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Adversarial Engine Active</span>
                            </div>
                        </div>
                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Perform 80% accuracy validation on my slip. Run Veto Phase analysis."); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, memo } from 'react';
import type { ChatMessage, OddsFormat, PropBet } from '../types';
import { PredictionDisplay } from './PredictionDisplay';
import { SendIcon, LogoIcon, PlusIcon } from './Icons';

interface ChatInterfaceProps {
    messages: ChatMessage[];
    isReplying: boolean;
    onSendMessage: (message: string, imageData?: { data: string, mimeType: string }) => void;
    oddsFormat: OddsFormat;
    onAnalyzeProp?: (prop: PropBet) => void;
    pickSlip?: PropBet[];
    onTogglePick?: (prop: PropBet) => void;
    onSearchPlayer?: (player: string) => void;
}

const renderMarkdownTable = (lines: string[], keyPrefix: string) => {
    const tableRows = lines.filter(line => !line.match(/^[|\-\s:]+$/) && line.includes('|'));

    if (tableRows.length < 2) return null;

    const headers = tableRows[0].split('|').filter(cell => cell.trim() !== '').map(c => c.trim());
    const dataRows = tableRows.slice(1).map(row => 
        row.split('|').filter(cell => cell.trim() !== '').map(c => c.trim())
    );

    return (
        <div key={`${keyPrefix}-table`} className="my-6 overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950/50">
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-[10px] text-left">
                    <thead className="bg-zinc-900/80">
                        <tr>
                            {headers.map((header, idx) => (
                                <th key={idx} className="px-4 py-3 font-black text-zinc-500 uppercase tracking-widest whitespace-nowrap border-b border-zinc-800">
                                    {header}
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-900">
                        {dataRows.map((row, rowIdx) => (
                            <tr key={rowIdx} className="hover:bg-amber-500/[0.02] transition-colors">
                                {row.map((cell, cellIdx) => (
                                    <td key={cellIdx} className="px-4 py-3 text-zinc-300 font-medium whitespace-nowrap tabular-nums">
                                        {cell}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

const renderBold = (text: string, key: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return (
        <span key={key}>
            {parts.map((part, index) => {
                if (part.startsWith('**') && part.endsWith('**')) {
                    return <strong key={index} className="text-amber-500 font-black">{part.slice(2, -2)}</strong>;
                }
                return part;
            })}
        </span>
    );
};

const renderModelContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let tableBuffer: string[] = [];

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();

        if (line.startsWith('|') && (line.endsWith('|') || line.split('|').length > 1)) {
            tableBuffer.push(line);
        } else {
            if (tableBuffer.length > 0) {
                elements.push(renderMarkdownTable(tableBuffer, `table-${i}`));
                tableBuffer = [];
            }

            if (line !== '') {
                elements.push(
                    <p key={`p-${i}`} className="mb-3 last:mb-0 leading-relaxed text-zinc-300">
                        {renderBold(line, `bold-${i}`)}
                    </p>
                );
            }
        }
    }

    if (tableBuffer.length > 0) {
        elements.push(renderMarkdownTable(tableBuffer, `table-end`));
    }

    return elements;
};

export const ChatInterface: React.FC<ChatInterfaceProps> = memo(({ messages, isReplying, onSendMessage, oddsFormat, onAnalyzeProp, pickSlip, onTogglePick, onSearchPlayer }) => {
    const [text, setText] = useState('');
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const endOfMessagesRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (text.trim() || selectedImage) {
            onSendMessage(text.trim(), selectedImage || undefined);
            setText('');
            setSelectedImage(null);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const base64 = (event.target?.result as string).split(',')[1];
                setSelectedImage({ data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };

    return (
        <div className="bg-zinc-950/90 backdrop-blur-xl rounded-[2.5rem] shadow-2xl border border-zinc-800 flex flex-col h-[75vh] max-h-[800px] overflow-hidden">
           <div className="px-6 py-4 border-b border-zinc-900 bg-black/40 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Deep Sync Terminal</span>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-[8px] font-black text-zinc-700 uppercase">Latency: 14ms</span>
                </div>
           </div>

           <div className="flex-grow p-6 overflow-y-auto space-y-8 custom-scrollbar">
                {messages.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                        <LogoIcon className="w-16 h-16 mb-4 text-zinc-700" />
                        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-700">Awaiting Signal Command</p>
                    </div>
                )}

                {messages.map((msg, index) => (
                    <div key={index} className={`flex gap-4 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        {msg.role === 'model' && (
                            <div className="flex-shrink-0 w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                <LogoIcon className="w-6 h-6 text-amber-500" />
                            </div>
                        )}

                        <div className={`w-full ${msg.role === 'user' ? 'max-w-md' : 'max-w-2xl'}`}>
                            {msg.imageData && (
                                <div className="mb-3 rounded-2xl overflow-hidden border border-zinc-800 max-w-xs ml-auto">
                                    <img src={`data:image/png;base64,${msg.imageData}`} alt="Screenshot Analysis" className="w-full h-auto opacity-80" />
                                </div>
                            )}
                            {typeof msg.content === 'object' ? (
                                <PredictionDisplay 
                                    prediction={msg.content} 
                                    oddsFormat={oddsFormat} 
                                    onAnalyzeProp={onAnalyzeProp}
                                    pickSlip={pickSlip}
                                    onTogglePick={onTogglePick}
                                    onSearchPlayer={onSearchPlayer}
                                />
                            ) : (
                                <div className={`px-5 py-4 rounded-3xl ${
                                    msg.role === 'user' 
                                        ? 'bg-zinc-100 text-black font-semibold ml-auto shadow-[0_4px_20px_rgba(0,0,0,0.4)]' 
                                        : 'bg-zinc-900/50 text-zinc-200 border border-zinc-800'
                                }`}>
                                    {msg.role === 'model' ? (
                                        <div className="text-[13px]">{renderModelContent(msg.content)}</div>
                                    ) : (
                                        <p className="whitespace-pre-wrap text-[13px] leading-relaxed">{msg.content}</p>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                ))}
                 {isReplying && (
                    <div className="flex gap-4 justify-start">
                        <div className="flex-shrink-0 w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                             <LogoIcon className="w-6 h-6 text-amber-500" />
                        </div>
                        <div className="px-5 py-4 rounded-3xl bg-zinc-900/50 border border-zinc-800">
                            <div className="flex items-center gap-3">
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce"></span>
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                                <span className="w-2 h-2 bg-amber-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                                <span className="text-[9px] font-black text-amber-500 uppercase tracking-widest ml-2">Grounding Search Results...</span>
                            </div>
                        </div>
                    </div>
                )}
                <div ref={endOfMessagesRef} />
            </div>

            <div className="p-6 border-t border-zinc-900 bg-black/20">
                {selectedImage && (
                    <div className="mb-4 relative inline-block group">
                        <img 
                            src={`data:image/png;base64,${selectedImage.data}`} 
                            className="w-20 h-20 object-cover rounded-xl border border-amber-500/40 opacity-80" 
                        />
                        <button 
                            onClick={() => setSelectedImage(null)}
                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                        <div className="absolute inset-0 bg-amber-500/10 pointer-events-none animate-pulse"></div>
                    </div>
                )}
                <form onSubmit={handleSubmit} className="flex items-center gap-3">
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        accept="image/*" 
                        className="hidden" 
                    />
                    <button
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        className="bg-zinc-900 text-zinc-400 rounded-2xl p-4 hover:text-white border border-zinc-800 transition-all"
                        title="Upload Prop Screenshot"
                    >
                        <PlusIcon className="w-6 h-6" />
                    </button>
                    <input
                        type="text"
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder={selectedImage ? "Scan these props..." : "Ask about Anthony Davis, Giannis, or upload a screenshot..."}
                        disabled={isReplying}
                        className="w-full bg-zinc-900/50 border border-zinc-800 rounded-2xl px-6 py-4 text-sm text-white focus:outline-none focus:border-amber-500/50 transition-all disabled:opacity-50"
                    />
                    <button
                        type="submit"
                        disabled={isReplying || (!text.trim() && !selectedImage)}
                        className="bg-amber-500 text-black rounded-2xl p-4 hover:bg-amber-400 disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed transition-all shadow-lg shadow-amber-500/10"
                        aria-label="Send message"
                    >
                        <SendIcon className="w-6 h-6" />
                    </button>
                </form>
            </div>
        </div>
    );
});

