async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let delay = 3000;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      const errorStr = JSON.stringify(error);
      const isQuotaError = error?.status === 429 || errorStr.includes('429') || errorStr.includes('RESOURCE_EXHAUSTED');
      const isServerError = error?.status >= 500 || errorStr.includes('500') || errorStr.includes('Rpc failed') || errorStr.includes('xhr error');

      if ((isQuotaError || isServerError) && i < maxRetries - 1) {
        console.warn(`PRO-N-OS: Signal interference (Code 429/5xx). Attempt ${i + 1}/${maxRetries}. Retrying in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        delay *= 2; 
        continue;
      }
      throw error;
    }
  }
  return await fn();
}

