export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const todayDate = new Date();
  const tomorrowDate = new Date(todayDate);
  tomorrowDate.setDate(tomorrowDate.getDate() + 1);

  const todayStr = todayDate.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
  const tomorrowStr = tomorrowDate.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `ALPHA RESEARCH COMMAND: Identify all active and upcoming ${sport} games for TODAY (${todayStr}) and TOMORROW (${tomorrowStr}). 

  CORE MISSION:
  1. ANALYZE SHARP DELTA: Compare opening lines vs current.
  2. DEEP ROSTER SCRUB: Verify injury statuses for Impact Players.
  3. REAL-TIME MARKET STATS: Return Spread, Moneyline, and Total.

  FORMAT: Return a VALID JSON object. 
  Structure: { "games": [{ "id": "uuid", "date": "Month Day, Year", "homeTeam": "full name", "awayTeam": "full name", "league": "${sport}", "time": "ET (e.g. 7:30 PM)", "status": "Scheduled|Live|Finished", "score": "string", "isMustWin": boolean, "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  const configWithSearch = { 
    tools: [{ googleSearch: {} }],
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  try {
    const response = await callWithRetry(async () => {
      return await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: configWithSearch as any
      });
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    console.error("Alpha schedule sync failed:", error);
    throw error;
  }
};

