async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 5): Promise<T> {
  let delay = 2000;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      const errorStr = JSON.stringify(error).toLowerCase();
      // Specifically target the RPC/XHR errors and 500 status codes
      const isTransient = 
        error?.status === 500 || 
        error?.status === 503 ||
        errorStr.includes('rpc failed') || 
        errorStr.includes('xhr error') || 
        errorStr.includes('500') ||
        errorStr.includes('429') ||
        errorStr.includes('resource_exhausted');

      if (isTransient && i < maxRetries - 1) {
        console.warn(`PRO-N-OS: Signal interference (Transient Error). Retry ${i + 1}/${maxRetries} in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        delay *= 1.5; // Exponential backoff
        continue;
      }
      throw error;
    }
  }
  return await fn();
}

