import React, { useState, useEffect, useRef } from 'react';
import { CoinIcon, HammerIcon, ChipIcon } from './Icons';
import type { MiningState } from '../types';

interface TokenomicsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const TokenomicsModal: React.FC<TokenomicsModalProps> = ({ isOpen, onClose }) => {
  const [mining, setMining] = useState<MiningState>({
    isMining: false,
    hps: 0,
    totalMined: 0,
    unpaidBalance: 0,
    algo: 'Ghostrider-Alpha'
  });
  const [logs, setLogs] = useState<string[]>(["[SYSTEM] Kernel initialized.", "[ALGO] Ghostrider v1.8 active."]);
  const hpsTimer = useRef<number | null>(null);

  useEffect(() => {
    if (mining.isMining) {
      hpsTimer.current = window.setInterval(() => {
        const randomHps = 450 + Math.random() * 150;
        setMining(prev => ({
          ...prev,
          hps: randomHps,
          unpaidBalance: prev.unpaidBalance + (randomHps / 1000000)
        }));

        if (Math.random() > 0.8) {
          const newLog = `[BLOCK] Validated segment @ ${Math.floor(randomHps)} H/s`;
          setLogs(prev => [newLog, ...prev].slice(0, 5));
        }
      }, 1000);
    } else {
      if (hpsTimer.current) clearInterval(hpsTimer.current);
      setMining(prev => ({ ...prev, hps: 0 }));
    }
    return () => { if (hpsTimer.current) clearInterval(hpsTimer.current); };
  }, [mining.isMining]);

  if (!isOpen) return null;

  return (
    <div 
        className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md"
        onClick={onClose}
    >
      <div 
