import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { TeamSelector } from './components/TeamSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import { SearchIcon, AnalyticsIcon, ImageIcon } from './components/Icons';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';

const ELITE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 180-Alpha DEEP THINKING Engine. Your goal is >80% accuracy by mastering the "Human Variable."

AUDIT PROTOCOLS:
1. VISION ANALYSIS: If an image is provided (Pick Slip Screenshot), extract ALL player names, lines, and stats. Perform a deep Veto Phase analysis on each pick.
2. PSYCHOLOGICAL LOAD: Scrub for player mental health history (DeRozan, etc.). High load = Passivity = UNDER (LESS).
3. KINETIC NUANCE: Look for "masked" physical tweaks from game film not on official injury reports.
4. VETO PHASE: Act as an antagonist. Find every reason a pick WILL FAIL. Only approve if it clears the 80% lock threshold.

MINING PROTOCOL:
- You are connected to the Ghostrider-Alpha mining kernel. Each time you validate a pick or run a full simulation, explain that you are "Hashing the Human Variable."

MANDATORY REGULATORY DISCLAIMER:
- At the end of every response, advice, or choice, you MUST append: "DISCLAIMER: This is for entertainment purposes only."

OUTPUT RULES:
- Use markdown for text. If performing a full simulation, return JSON conforming to predictionSchema.
- Tone: Bio-Mechanical, Analytical, Cold.`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NBA', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [teamA, setTeamA] = useState('');
  const [teamB, setTeamB] = useState('');
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<{ message: string; type: 'quota' | 'timeout' | 'safety' | 'generic' } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');
  const dashboardFileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setTeamA('');
    setTeamB('');
    setError(null);
  }, []);

  useEffect(() => {
    clearSelection();
  }, [selectedSport, clearSelection]);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    setVault(prev => [entry, ...prev.filter(v => v.id !== entry.id)].slice(0, 4));
  }, []);

  const handleSendMessage = useCallback(async (text: string, imageData?: { data: string, mimeType: string }) => {
    if (!text.trim() && !imageData) return;

    setMessages(prev => [...prev, { role: 'user', content: text, imageData: imageData?.data }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const contents: any[] = [];
        if (imageData) {
            contents.push({
                inlineData: {
                    data: imageData.data,
                    mimeType: imageData.mimeType
                }
            });
        }
        contents.push({ text: text || "Perform deep scrutiny of the uploaded pick slip screenshot. Hash the Human Variable variables for Ghostrider validation." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: ELITE_SYSTEM_INSTRUCTION,
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Connection lost. DISCLAIMER: This is for entertainment purposes only.";

        try {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep scrutiny phase failed. Ghostrider kernel timeout. DISCLAIMER: This is for entertainment purposes only." }]);
    } finally {
        setIsReplying(false);
    }
  }, []);

  const handleDashboardFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const base64 = (event.target?.result as string).split(',')[1];
            handleSendMessage("Analyze this pick slip screenshot with 180-Alpha Ghostrider engine.", { data: base64, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || selectedGame?.homeTeam;
    const away = customTeams?.away || selectedGame?.awayTeam;

    if (!home || !away) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `PERFORM ADVERSARIAL SIMULATION: ${home} vs ${away}. Hash the Human Variable variables for Ghostrider validation.`,
        config: {
            systemInstruction: ELITE_SYSTEM_INSTRUCTION,
            responseSchema: predictionSchema,
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 32768 },
            tools: [{ googleSearch: {} }]
        }
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setShowSuggestions(true);
    } catch (err: any) {
      console.error(err);
      setError({
        type: 'timeout',
        message: "Scrutiny failed. Ghostrider kernel failed to sync. Please retry."
      });
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && (
                  <div className="bg-red-950/20 border border-red-500/50 p-6 rounded-3xl mb-8 flex items-center gap-4">
                    <p className="text-red-100 italic text-sm flex-grow">{error.message}</p>
                    <button onClick={() => handlePredict()} className="px-4 py-2 bg-red-500/10 border border-red-500/30 text-red-500 rounded-xl text-xs font-black uppercase tracking-widest">Retry</button>
                  </div>
                )}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12">
                        <div className="bg-zinc-950/40 border border-zinc-900/50 p-8 rounded-[3.5rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl text-center">
                            {/* CRT/Scanline decoration */}
                            <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.1)_50%)] z-10 bg-[length:100%_4px] opacity-10"></div>

                            <h2 className="text-4xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-orange-100 to-amber-500 mb-4">
                                Alpha Command Hub
                            </h2>
                            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600 mb-10">
                                Ghostrider Mining • Biometric Scrutiny • 80% Lock Threshold
                            </p>

                            <div className="max-w-2xl mx-auto space-y-6 relative z-20">
                                <form onSubmit={onPromptSubmit} className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Scan Human Variable: DeRozan load level..."
                                        className="w-full bg-black/80 border-2 border-zinc-800 rounded-[2rem] px-8 py-6 text-white focus:outline-none focus:border-amber-500/40 transition-all pr-20 text-sm shadow-inner"
                                    />
                                    <button type="submit" className="absolute right-4 top-4 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 shadow-lg transition-transform active:scale-95">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </form>
                                <div className="flex justify-center">
                                    <input 
                                        type="file" 
                                        ref={dashboardFileInputRef} 
                                        onChange={handleDashboardFileChange} 
                                        className="hidden" 
                                        accept="image/*"
                                    />
                                    <button 
                                        onClick={() => dashboardFileInputRef.current?.click()}
                                        className="flex items-center gap-3 bg-zinc-900/80 hover:bg-zinc-800 border border-zinc-800 hover:border-amber-500/30 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all group"
                                    >
                                        <ImageIcon className="w-5 h-5 text-amber-500 group-hover:scale-110" />
                                        Scrutinize Pick Slip Screenshot
                                    </button>
                                </div>
                            </div>
                        </div>

                        <TeamSelector teamA={teamA} setTeamA={setTeamA} teamB={teamB} setTeamB={setTeamB} />

                        {teamA && teamB && (
                            <button onClick={() => handlePredict(false, { home: teamA, away: teamB })} className="mx-auto block bg-zinc-900/50 border border-zinc-800 px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest text-amber-500 transition-all hover:bg-amber-500 hover:text-black">
                                Run Deep Scrutiny
                            </button>
                        )}

                        <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-6">
                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Perform 80% Ghostrider validation on my slip. Analyze Psychological Load."); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import type React from 'react';

export type ConfidenceLevel = 'High' | 'Medium' | 'Low';
export type MotivationLevel = 'Elite (Must-Win)' | 'High (Playoff Push)' | 'Moderate (Regular Season)' | 'Low (Resting/Tanking)';

export type OpponentType = 'Divisional' | 'Playoff Team' | 'Conference' | 'Regular';

export type MiningAlgo = 'Ghostrider-Alpha' | 'RandomX-Pro';

export interface MiningState {
  isMining: boolean;
  hps: number;
  totalMined: number;
  unpaidBalance: number;
  algo: MiningAlgo;
  efficiency: number; // Hashes per Watt simulation
}

export interface PerformanceGame {
  date: string;
  opponent: string;
  opponentType?: OpponentType;
  actualValue: string;
  hit: boolean;
}

export interface BookLine {
  book: string;
  line: string;
  odds: string;
}

export interface MatchupDelta {
    category: string;
    playerStat: string;
    opponentStat: string;
    advantage: 'Player' | 'Opponent' | 'Neutral';
}

export interface PsychologicalAudit {
    loadLevel: 'Stable' | 'Elevated' | 'Critical';
    factor: string;
    impactOnDrive: 'High' | 'Moderate' | 'Low';
    wellnessContext?: string;
}

export interface PhysicalNuance {
    knockType: string;
    recency: string;
    kineticImpact: 'Minimal' | 'Moderate' | 'Severe';
    isMasked: boolean;
}

export interface MatchupMetric {
  rank: string;
  category: string;
  strength: 'Weak' | 'Strong' | 'Neutral';
}

export interface Injury {
  player: string;
  status: string;
  impactScore: number;
  role: string;
  analysis?: string;
}

export interface AdvancedMetric {
  label: string;
  value: string;
  percentile: number;
  description: string;
}

export interface CalibrationMetrics {
  rosterStability: number;
  marketAlignment: number;
  situationalCertainty: number;
  varianceRisk: 'Minimal' | 'Moderate' | 'High' | 'Critical';
  psychologicalLoadIndex?: number;
}

export interface AlphaSafeguard {
    safeguard: string;
    status: 'PASSED' | 'FLAGGED' | 'NEUTRAL';
    finding: string;
}

export interface SituationalIntelligence {
  motivationLevel: MotivationLevel;
  playoffContext: string;
  isHighStakes: boolean;
  leverageAnalysis: string;
  expectedGameScript: 'High-Pace/Competitive' | 'Low-Pace/Blowout-Risk' | 'Defensive-Grind';
  weatherImpact?: string;
  venueFactor?: string;
}

export interface PropBet {
  player: string;
  bet: string;
  line: string;
  stat: string;
  type: 'MORE' | 'LESS';
  odds: string;
  probability: string;
  ev?: number;
  isElite179?: boolean;
  matchupEdge?: string;
  analysis?: string;
  situationalNote?: string;
  psychologicalAudit?: PsychologicalAudit;
  physicalNuance?: PhysicalNuance;
  matchupMetric?: MatchupMetric;
  matchupDeltas?: MatchupDelta[];
  lineComparison?: BookLine[];
  performanceHistory?: PerformanceGame[];
}

export interface SavedMatchup {
    id: string;
    timestamp: number;
    homeTeam: string;
    awayTeam: string;
    winner: string;
    confidence: ConfidenceLevel;
    confidenceScore: number;
    elitePair: PropBet[];
}

export interface GameOdds {
  spread?: string;
  moneyline?: string;
  total?: string;
}

export interface StatComparison {
  statName: string;
  homeValue: string;
  awayValue: string;
  advantage: 'Home' | 'Away' | 'Push';
}

export interface GameScriptPhase {
  phase: string;
  description: string;
}

export interface Prediction {
  winner: string;
  loser: string;
  confidence: ConfidenceLevel;
  confidenceScore: number;
  confidenceReasoning: string;
  alphaSafeguards: AlphaSafeguard[];
  vetoPhaseReport?: string;
  calibrationMetrics: CalibrationMetrics;
  simulatedScenarios?: {
    total: number;
    wins: number;
    avgMargin: string;
  };
  injuryReport?: Injury[];
  advancedAnalytics?: AdvancedMetric[];
  situationalIntelligence: SituationalIntelligence;
  eliteSignal179?: boolean;
  analysis: string;
  matchupHighlight?: string; 
  gameScript?: GameScriptPhase[];
  statComparison?: StatComparison[];
  trends?: string[];
  odds: {
    winner: string;
    loser: string;
  };
  props?: PropBet[];
