async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 4): Promise<T> {
  let delay = 1500;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      const errorStr = JSON.stringify(error).toLowerCase();
      // Expanded detection for transient RPC/XHR failures and internal server errors
      const isTransient = 
        error?.status === 500 || 
        error?.status === 503 ||
        error?.status === 504 ||
        errorStr.includes('rpc failed') || 
        errorStr.includes('xhr error') || 
        errorStr.includes('500') ||
        errorStr.includes('429') ||
        errorStr.includes('resource_exhausted') ||
        errorStr.includes('deadline_exceeded') ||
        errorStr.includes('internal error');

      if (isTransient && i < maxRetries - 1) {
        console.warn(`PRO-N-OS: Kernel signal interference. Attempting resync ${i + 1}/${maxRetries} in ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        delay *= 2; // Exponential backoff
        continue;
      }
      throw error;
    }
  }
  return await fn();
}

