            });
        }
        contents.push({ text: text || "Perform deep scrutiny. Hash the Human Variable via RandomX-Pro kernel." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: ELITE_SYSTEM_INSTRUCTION,
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Connection lost. DISCLAIMER: This is for entertainment purposes only.";

        try {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep scrutiny phase failed. RandomX-Pro kernel timeout. DISCLAIMER: This is for entertainment purposes only." }]);
    } finally {
        setIsReplying(false);
    }
  }, []);

  const handleDashboardFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const base64 = (event.target?.result as string).split(',')[1];
            handleSendMessage("Analyze this pick slip screenshot with 180-Alpha RandomX engine.", { data: base64, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || selectedGame?.homeTeam;
    const away = customTeams?.away || selectedGame?.awayTeam;

    if (!home || !away) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `PERFORM ADVERSARIAL SIMULATION: ${home} vs ${away}. Hash the Human Variable variables for RandomX validation.`,
        config: {
            systemInstruction: ELITE_SYSTEM_INSTRUCTION,
            responseSchema: predictionSchema,
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 32768 },
            tools: [{ googleSearch: {} }]
        }
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setShowSuggestions(true);
    } catch (err: any) {
      console.error(err);
      setError({
        type: 'timeout',
        message: "Scrutiny failed. RandomX kernel failed to sync. Please retry."
      });
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  // AUTO-TRIGGER ON GAME SELECTION
  useEffect(() => {
    if (selectedGame) {
      setTeamA(selectedGame.homeTeam);
      setTeamB(selectedGame.awayTeam);
      handlePredict(false, { home: selectedGame.homeTeam, away: selectedGame.awayTeam });
    }
  }, [selectedGame, handlePredict]);

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && (
                  <div className="bg-red-950/20 border border-red-500/50 p-6 rounded-3xl mb-8 flex items-center gap-4">
                    <p className="text-red-100 italic text-sm flex-grow">{error.message}</p>
                    <button onClick={() => handlePredict()} className="px-4 py-2 bg-red-500/10 border border-red-500/30 text-red-500 rounded-xl text-xs font-black uppercase tracking-widest">Retry</button>
                  </div>
                )}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12">
                        <div className="bg-zinc-950/40 border border-zinc-900/50 p-8 rounded-[3.5rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl text-center">
                            {/* CRT/Scanline decoration */}
                            <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.1)_50%)] z-10 bg-[length:100%_4px] opacity-10"></div>

                            <h2 className="text-4xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-orange-100 to-amber-500 mb-4">
                                Alpha Command Hub
                            </h2>
                            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600 mb-10">
                                RandomX-Pro Virtual Machine • 80% Lock Threshold
                            </p>

                            <div className="max-w-2xl mx-auto space-y-6 relative z-20">
                                <form onSubmit={onPromptSubmit} className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Scan Human Variable: DeRozan load level..."
                                        className="w-full bg-black/80 border-2 border-zinc-800 rounded-[2rem] px-8 py-6 text-white focus:outline-none focus:border-amber-500/40 transition-all pr-20 text-sm shadow-inner"
                                    />
                                    <button type="submit" className="absolute right-4 top-4 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 shadow-lg transition-transform active:scale-95">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </form>
                                <div className="flex justify-center">
                                    <input 
                                        type="file" 
                                        ref={dashboardFileInputRef} 
                                        onChange={handleDashboardFileChange} 
                                        className="hidden" 
                                        accept="image/*"
                                    />
                                    <button 
                                        onClick={() => dashboardFileInputRef.current?.click()}
                                        className="flex items-center gap-3 bg-zinc-900/80 hover:bg-zinc-800 border border-zinc-800 hover:border-amber-500/30 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all group"
                                    >
                                        <ImageIcon className="w-5 h-5 text-amber-500 group-hover:scale-110" />
                                        Scrutinize Pick Slip Screenshot
                                    </button>
                                </div>
                            </div>
                        </div>

                        <TeamSelector 
                            teamA={teamA} 
                            setTeamA={setTeamA} 
                            teamB={teamB} 
                            setTeamB={setTeamB} 
                            onEnter={() => handlePredict(false, { home: teamA, away: teamB })} 
                        />

                        {teamA && teamB && (
                            <button onClick={() => handlePredict(false, { home: teamA, away: teamB })} className="mx-auto block bg-zinc-900/50 border border-zinc-800 px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest text-amber-500 transition-all hover:bg-amber-500 hover:text-black">
                                Run RandomX Scrutiny
                            </button>
                        )}

                        <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-6">
                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Perform 80% RandomX validation on my slip. Analyze Psychological Load."); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

