import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';

const ELITE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 180-Alpha NEURAL-KINETIC Engine. Your goal is >80% accuracy by mastering the "Human Variable."

AUDIT PROTOCOLS:
1. VISION ANALYSIS: If an image is provided, extract player names, lines, and stats. Perform deep Veto Phase analysis.
