export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `ALPHA RESEARCH COMMAND: Identify all active/upcoming ${sport} games for ${today}. 
  FORMAT: Return a VALID JSON object. 
  Structure: { "games": [{ "id": "uuid", "date": "Month Day, Year", "homeTeam": "full name", "awayTeam": "full name", "league": "${sport}", "time": "ET", "status": "Scheduled|Live|Finished", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  try {
    const response = await callWithRetry(async () => {
      // Switched to gemini-3-flash-preview for high-frequency grounding tasks to avoid 429 quota errors seen on Pro
      return await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json' 
        }
      });
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    console.error("Alpha schedule sync failed:", error);
    throw error; // Rethrow to let UI handle the error state
  }
};

