export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `ALPHA RESEARCH COMMAND: Identify all active/upcoming ${sport} games for ${today}. 
  FORMAT: Return a VALID JSON object adhering to the schema.
  Include Spread, Moneyline, and Over/Under totals if available.`;

  try {
    const response = await callWithRetry(async () => {
      // Switched to gemini-3-pro-preview for reliable grounding and schema adherence to prevent 500 RPC errors
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json',
          responseSchema: scheduleSchema 
        }
      });
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    console.error("Alpha schedule sync failed:", error);
    throw error;
  }
};

