  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const getSystemInstruction = useCallback(() => {
      let instruction = BASE_SYSTEM_INSTRUCTION;
      if (memory.axioms.length > 0) {
          instruction += `\n\n*** INTERNAL KNOWLEDGE BASE (LESSONS LEARNED) - STRICTLY ADHERE TO THESE RULES ***\n`;
          memory.axioms.forEach(a => {
              instruction += `- [WEIGHT: ${a.weight}] ${a.rule} (Learned from ${a.sourceMatchup})\n`;
          });
      }
      instruction += `\n\nMANDATORY DISCLAIMER: Every response must end with "DISCLAIMER: This is for entertainment purposes only."`;
      return instruction;
  }, [memory]);

  const checkLimit = useCallback(() => {
    if (isPremium) return true;

    const today = new Date().toDateString();
    const usageData = localStorage.getItem('prognos_usage');
    let usage = usageData ? JSON.parse(usageData) : { date: today, count: 0 };

    if (usage.date !== today) {
        usage = { date: today, count: 0 };
    }

    if (usage.count >= FREE_LIMIT) {
        setIsSubscriptionOpen(true);
        return false;
    }

    usage.count += 1;
    localStorage.setItem('prognos_usage', JSON.stringify(usage));
    return true;
  }, [isPremium]);

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setTeamA('');
    setTeamB('');
    setError(null);
    setShowSuggestions(false);
  }, []);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    const newVault = [entry, ...vault.filter(v => v.id !== entry.id)].slice(0, 4);
    setVault(newVault);
    localStorage.setItem('prognosVault', JSON.stringify(newVault));
  }, [vault]);

  const handleSendMessage = useCallback(async (text: string, imageData?: { data: string, mimeType: string }) => {
    if (!text.trim() && !imageData) return;

    setMessages(prev => [...prev, { role: 'user', content: text, imageData: imageData?.data }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const contents: any[] = [];
        if (imageData) {
            contents.push({ inlineData: { data: imageData.data, mimeType: imageData.mimeType } });
        }
        contents.push({ text: text || "Perform neural scrutiny with high-fidelity passion." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: getSystemInstruction(),
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Neural connection flatlined. DISCLAIMER: This is for entertainment purposes only.";

        try {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep scrutiny heart failure. Signal lost. DISCLAIMER: This is for entertainment purposes only." }]);
    } finally {
        setIsReplying(false);
    }
  }, [getSystemInstruction]);

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || teamA;
    const away = customTeams?.away || teamB;

    if (!home || !away) return;

    // Check Freemium Limit
    if (!checkLimit()) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `PERFORM PASSIONATE NEURAL MAPPING: ${home} vs ${away}. Scrutinize the kinetic masterpiece for 80% lock.`,
        config: {
            systemInstruction: getSystemInstruction(),
            responseSchema: predictionSchema,
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 32768 },
            tools: [{ googleSearch: {} }]
        }
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setShowSuggestions(true);
    } catch (err: any) {
      setError({ type: 'timeout', message: "Neural heartbeat irregular. Please retry analysis." });
    } finally {
      setIsLoading(false);
    }
  }, [teamA, teamB, addToVault, checkLimit, getSystemInstruction]);

  const runNeuralOptimization = async () => {
      if (vault.length === 0) {
          alert("Vault is empty. No data to reflect upon.");
          return;
      }
      setIsReflectionOpen(true);
      try {
          const result = await generateReflection(vault);
          setRecentAxioms(result.axioms);
          setRecentSummary(result.summary);
          setLevelUp(result.levelUp);

          // Update Memory
          const newMemory: NeuralMemory = {
              axioms: [...result.axioms, ...memory.axioms].slice(0, 20), // Keep latest 20 rules
              evolutionLevel: memory.evolutionLevel + result.levelUp,
              lastOptimization: Date.now()
          };
          setMemory(newMemory);
          localStorage.setItem('prognos_memory', JSON.stringify(newMemory));
      } catch (e) {
          console.error(e);
          setIsReflectionOpen(false);
      }
  };

  useEffect(() => {
    if (selectedGame && !prediction) {
      setTeamA(selectedGame.homeTeam);
      setTeamB(selectedGame.awayTeam);
      handlePredict(false, { home: selectedGame.homeTeam, away: selectedGame.awayTeam });
    }
  }, [selectedGame, handlePredict, prediction]);

  const handleDashboardFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const base64 = (event.target?.result as string).split(',')[1];
            handleSendMessage("Analyze this pick slip with obsessive neural scrutiny.", { data: base64, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden relative">
      <BackgroundArt />
      <SubscriptionModal isOpen={isSubscriptionOpen} onClose={() => setIsSubscriptionOpen(false)} onUpgrade={() => { setIsPremium(true); setIsSubscriptionOpen(false); }} />
      <ReflectionModal 
        isOpen={isReflectionOpen} 
        onClose={() => setIsReflectionOpen(false)} 
        axioms={recentAxioms} 
        summary={recentSummary} 
        levelUp={levelUp}
        currentLevel={memory.evolutionLevel}
      />

      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
        onOpenReflection={runNeuralOptimization}
      />

      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 relative z-10 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>

        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => { setVault([]); localStorage.removeItem('prognosVault'); }} onRemove={(id) => {
                const newVault = vault.filter(x => x.id !== id);
                setVault(newVault);
                localStorage.setItem('prognosVault', JSON.stringify(newVault));
            }} />
        ) : (
            <>
                {error && (
                  <div className="bg-red-950/20 border border-red-500/50 p-6 rounded-3xl mb-8 flex items-center gap-4 animate-fade-in tactical-outline">
                    <p className="text-red-100 italic text-sm flex-grow">{error.message}</p>
                    <button onClick={() => handlePredict()} className="px-4 py-2 bg-red-500/10 border border-red-500/30 text-red-500 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">Retry</button>
                  </div>
                )}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12 animate-fade-in">
                        <div className="bg-zinc-950/40 border-2 border-zinc-800 p-10 rounded-[4rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl text-center tactical-outline scanline-sweep">
                            <h2 className="text-5xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-orange-100 to-amber-500 mb-4">
                                Alpha Command Hub
                            </h2>
                            <p className="text-[11px] font-black uppercase tracking-[0.5em] text-amber-500/60 mb-10">
                                Neural-Kinetic Intelligence • Obsessively Driven
                            </p>

                            <div className="max-w-2xl mx-auto space-y-8 relative z-20">
                                <form onSubmit={onPromptSubmit} className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Scan Human Variable: Psychological Pulse..."
                                        className="w-full bg-black/60 border-2 border-zinc-800 rounded-[2rem] px-8 py-7 text-white focus:outline-none focus:border-amber-500/60 transition-all pr-20 text-sm shadow-2xl"
                                    />
                                    <button type="submit" className="absolute right-5 top-5 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 shadow-lg transition-transform active:scale-95">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </form>

                                <div className="flex flex-col items-center">
                                    <input 
                                        type="file" 
                                        ref={dashboardFileInputRef} 
                                        onChange={handleDashboardFileChange} 
                                        className="hidden" 
                                        accept="image/*"
                                    />
                                    <button 
                                        onClick={() => dashboardFileInputRef.current?.click()}
                                        className="flex items-center gap-4 bg-zinc-900/60 hover:bg-zinc-800 border-2 border-zinc-800 hover:border-amber-500/40 px-10 py-5 rounded-[2.5rem] transition-all group/upload active:scale-95"
                                    >
                                        <div className="bg-amber-500/10 p-2 rounded-xl border border-amber-500/30">
                                            <ImageIcon className="w-6 h-6 text-amber-500 group-hover/upload:scale-110 transition-transform" />
                                        </div>
                                        <div className="text-left">
                                            <span className="block text-[10px] font-black text-white uppercase tracking-widest">Scrutinize Pick Slip</span>
                                            <span className="block text-[8px] font-bold text-zinc-500 uppercase tracking-widest">Vision-Pulse Analysis</span>
                                        </div>
                                    </button>
                                </div>
                            </div>
                        </div>

                        <TeamSelector 
                            teamA={teamA} 
                            setTeamA={setTeamA} 
                            teamB={teamB} 
                            setTeamB={setTeamB} 
                            onEnter={() => handlePredict(false, { home: teamA, away: teamB })} 
                        />

                        {teamA && teamB && (
                            <button onClick={() => handlePredict(false, { home: teamA, away: teamB })} className="mx-auto block bg-zinc-950 border-2 border-zinc-800 px-12 py-5 rounded-3xl text-[11px] font-black uppercase tracking-[0.3em] text-amber-500 transition-all hover:bg-amber-500 hover:text-black hover:scale-105 active:scale-95 shadow-2xl tactical-outline">
                                Initiate Deep Scrutiny
                            </button>
                        )}

                        <div className="space-y-12">
                          <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                          <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                        </div>
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-6 animate-fade-in relative z-20">
                        <div className="flex justify-between items-center mb-6">
                          <button 
                            onClick={clearSelection} 
                            className="flex items-center gap-4 text-[11px] font-black uppercase tracking-[0.4em] text-zinc-500 hover:text-amber-500 transition-all group px-6 py-3 bg-zinc-900/40 rounded-2xl border border-zinc-800 hover:border-amber-500/40"
                          >
                            <svg className="w-4 h-4 transition-transform group-hover:-translate-x-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                            Neural Reset
                          </button>

                          <div className="flex items-center gap-2">
                             <div className="w-2.5 h-2.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_10px_orange]"></div>
                             <span className="text-[10px] font-black uppercase tracking-[0.4em] text-amber-500 italic">Neural Lock Active</span>
                          </div>
                        </div>

                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}

                        <button 
                          onClick={clearSelection}
                          className="w-full py-10 mt-12 rounded-[4rem] border-4 border-dashed border-zinc-900 text-zinc-700 text-[12px] font-black uppercase tracking-[1em] hover:border-amber-500/40 hover:text-amber-500 transition-all bg-black/40 backdrop-blur-xl group/reset"
                        >
                          <span className="group-hover/reset:scale-110 transition-transform block">Purge Current Neural Command Path</span>
                        </button>
                    </div>
                )}
            </>
        )}
      </main>

      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Perform obsessive neural audit on my slip. Scrutinize every detail."); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
    </div>
  );
};

