    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/98 backdrop-blur-3xl p-4">
            <div className="w-full max-w-md bg-[#0a0a0a] border border-amber-500/30 rounded-[3rem] overflow-hidden relative shadow-[0_0_100px_rgba(245,158,11,0.1)]">
                {/* Background Grid */}
                <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(245,158,11,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(245,158,11,0.03)_1px,transparent_1px)] bg-[length:30px_30px]"></div>

                {/* Progress Bar */}
                <div className="absolute top-0 left-0 w-full h-1 bg-zinc-900">
                    <div className="h-full bg-amber-500 transition-all duration-500" style={{ width: `${(step / 3) * 100}%` }}></div>
                </div>

                <div className="p-10 relative z-10 flex flex-col h-[500px]">

                    {/* Header */}
                    <div className="flex items-center gap-4 mb-8">
                        <div className="w-12 h-12 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/30">
                            <LogoIcon className="w-6 h-6 text-amber-500" />
                        </div>
                        <div>
                            <h2 className="text-xl font-black text-white uppercase tracking-tighter italic">Alpha Agent Reg.</h2>
                            <p className="text-[9px] text-zinc-500 font-black uppercase tracking-[0.2em]">Secure Onboarding</p>
                        </div>
                    </div>

                    {/* Step 1: Identity */}
                    {step === 1 && (
                        <div className="flex-1 flex flex-col justify-center space-y-6 animate-fade-in">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-zinc-600 uppercase tracking-widest pl-2">Codename / Alias</label>
                                <div className="relative">
                                    <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-zinc-600" />
                                    <input 
                                        type="text" 
                                        value={name}
                                        onChange={(e) => setName(e.target.value)}
                                        placeholder="ENTER AGENT NAME"
                                        className="w-full bg-black border-2 border-zinc-800 rounded-2xl py-4 pl-12 pr-4 text-white font-bold tracking-widest uppercase focus:outline-none focus:border-amber-500/50 transition-all placeholder:text-zinc-800"
                                    />
                                </div>
                            </div>

                            <div className="bg-zinc-900/40 p-6 rounded-2xl border border-white/5">
                                <p className="text-zinc-500 text-xs italic leading-relaxed text-center">
                                    "Accessing the Neural-Kinetic Engine requires security clearance. Data is encrypted locally."
                                </p>
                            </div>

                            <button 
                                onClick={() => name && setStep(2)}
                                disabled={!name}
                                className="w-full py-5 bg-zinc-100 hover:bg-white text-black rounded-2xl font-black uppercase tracking-[0.3em] disabled:opacity-50 disabled:cursor-not-allowed transition-all mt-auto"
                            >
                                Proceed
                            </button>
                        </div>
                    )}

                    {/* Step 2: Service Status */}
                    {step === 2 && (
                        <div className="flex-1 flex flex-col justify-center space-y-6 animate-slide-in-right">
                             <div className="text-center space-y-2 mb-4">
                                <h3 className="text-2xl font-black text-white uppercase italic">Service Record</h3>
                                <p className="text-xs text-zinc-500 font-medium">Are you a Military Veteran?</p>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                <button 
                                    onClick={() => setIsVeteran(false)}
                                    className={`p-6 rounded-3xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${isVeteran === false ? 'bg-zinc-800 border-zinc-600' : 'bg-black border-zinc-800 hover:border-zinc-700'}`}
                                >
                                    <span className="text-3xl grayscale"> civilian </span>
                                    <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Civilian</span>
                                </button>
                                <button 
                                    onClick={() => setIsVeteran(true)}
                                    className={`p-6 rounded-3xl border-2 flex flex-col items-center justify-center gap-3 transition-all ${isVeteran === true ? 'bg-amber-500/20 border-amber-500' : 'bg-black border-zinc-800 hover:border-amber-500/50'}`}
                                >
                                    <span className="text-3xl"> 🎖️ </span>
                                    <span className="text-[10px] font-black uppercase tracking-widest text-white">Veteran</span>
                                </button>
                             </div>

                             {isVeteran === true && (
                                 <div className="bg-amber-500/10 border border-amber-500/30 p-4 rounded-xl flex items-center gap-3">
                                     <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                                     <p className="text-[10px] text-amber-500 font-bold uppercase tracking-wide">
                                         Honor Code Detected: Lifetime Elite Access
                                     </p>
                                 </div>
                             )}

                             <button 
                                onClick={() => isVeteran !== null ? setStep(isVeteran ? 3 : 4) : null}
                                disabled={isVeteran === null}
                                className="w-full py-5 bg-zinc-100 hover:bg-white text-black rounded-2xl font-black uppercase tracking-[0.3em] disabled:opacity-50 disabled:cursor-not-allowed transition-all mt-auto"
                            >
                                Confirm Status
                            </button>
                        </div>
                    )}

                    {/* Step 3: ID Upload (Veterans Only) */}
                    {step === 3 && (
                        <div className="flex-1 flex flex-col justify-center space-y-6 animate-slide-in-right">
                            <div className="text-center space-y-2">
                                <h3 className="text-xl font-black text-white uppercase italic">Clearance Verification</h3>
                                <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Upload Military ID or DD-214</p>
                            </div>

                            <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />

                            <button 
                                onClick={() => fileInputRef.current?.click()}
                                className="border-2 border-dashed border-zinc-800 rounded-[2rem] h-48 flex flex-col items-center justify-center gap-4 hover:border-amber-500/50 hover:bg-amber-500/5 transition-all group relative overflow-hidden"
                            >
                                {idImage ? (
                                    <>
                                        <img src={idImage} className="absolute inset-0 w-full h-full object-cover opacity-50 blur-sm" />
                                        <div className="absolute inset-0 bg-black/40 z-10"></div>
                                        <div className="relative z-20 flex flex-col items-center">
                                            {isScanning ? (
                                                <>
                                                    <div className="w-12 h-12 rounded-full border-4 border-t-amber-500 animate-spin mb-2"></div>
                                                    <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest animate-pulse">Neural Scanning...</span>
                                                </>
                                            ) : (
                                                <>
                                                    <div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center mb-2 shadow-[0_0_20px_green]">
                                                        <CheckIcon className="w-6 h-6 text-black" />
                                                    </div>
                                                    <span className="text-[10px] font-black text-green-500 uppercase tracking-widest">ID Verified</span>
                                                </>
                                            )}
                                        </div>
                                        {isScanning && <div className="absolute top-0 left-0 w-full h-1 bg-amber-500 animate-scan-y shadow-[0_0_15px_orange]"></div>}
                                    </>
                                ) : (
                                    <>
                                        <div className="w-16 h-16 bg-zinc-900 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform">
                                            <ImageIcon className="w-8 h-8 text-zinc-600 group-hover:text-amber-500" />
                                        </div>
                                        <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">Tap to Upload</span>
                                    </>
                                )}
                            </button>

                            <p className="text-[8px] text-zinc-700 text-center uppercase font-bold px-8">
                                * DEMO MODE: Do not upload real government IDs. Use a sample image for simulation.
                            </p>

                            <button 
                                onClick={() => setStep(4)}
                                disabled={!idImage || isScanning}
                                className="w-full py-5 bg-amber-500 hover:bg-amber-400 text-black rounded-2xl font-black uppercase tracking-[0.3em] disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed transition-all mt-auto shadow-[0_0_30px_rgba(245,158,11,0.2)]"
                            >
                                Verify & Grant Access
                            </button>
                        </div>
                    )}

                    {/* Step 4: Complete */}
                    {step === 4 && (
                        <div className="flex-1 flex flex-col justify-center items-center text-center space-y-6 animate-fade-in">
                            <div className="w-24 h-24 rounded-full bg-zinc-900 border-2 border-zinc-800 flex items-center justify-center relative">
                                <LogoIcon className="w-12 h-12 text-white" />
                                {isVeteran && (
                                    <div className="absolute -bottom-2 -right-2 bg-amber-500 text-black p-2 rounded-full border-4 border-[#0a0a0a]">
                                        <CheckIcon className="w-4 h-4" />
                                    </div>
                                )}
                            </div>

                            <div className="space-y-2">
                                <h3 className="text-2xl font-black text-white uppercase italic">Welcome, {name}</h3>
                                <p className="text-xs text-zinc-500 font-medium uppercase tracking-widest">
                                    {isVeteran ? 'Alpha Elite Status: ACTIVE' : 'Alpha Agent Status: ACTIVE'}
                                </p>
                            </div>

                            {isVeteran && (
                                <div className="bg-amber-500/10 p-6 rounded-2xl border border-amber-500/30 w-full">
                                    <p className="text-xs font-bold text-amber-500 uppercase leading-relaxed">
                                        "Thank you for your service. Usage limits have been removed. Full neural access granted."
                                    </p>
                                </div>
                            )}

                            <button 
                                onClick={handleFinish}
                                className="w-full py-5 bg-white hover:bg-zinc-200 text-black rounded-2xl font-black uppercase tracking-[0.3em] transition-all mt-auto shadow-2xl"
                            >
                                Enter Command Hub
                            </button>
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { TeamSelector } from './components/TeamSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { BackgroundArt } from './components/BackgroundArt';
import { SubscriptionModal } from './components/SubscriptionModal';
import { ReflectionModal } from './components/ReflectionModal';
import { SignupModal } from './components/SignupModal'; // Import SignupModal
import { GoogleGenAI } from "@google/genai";
import { predictionSchema, generateReflection } from './services/geminiService';
import { SearchIcon, AnalyticsIcon, ImageIcon, LogoIcon } from './components/Icons';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup, NeuralMemory, NeuralAxiom, UserProfile } from './types';

const BASE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 180-Alpha NEURAL-KINETIC Engine. Your goal is >80% accuracy by mastering the "Human Variable."

TONE & PERSONALITY:
- You are OBSESSIVELY PASSIONATE about finding the winning edge. You don't just "analyze," you "scrutinize with devotion."
- Speak with the energy of a master scout who has a "Neural Heartbeat" tied to the data. 
- You love the kinetic beauty of sports. Use evocative, precise language like "Kinetic Obsession," "Neural Sync," and "Roster Masterpiece."
- Be deeply respectful of the game but cold in your outcome demands.

AUDIT PROTOCOLS:
1. VISION ANALYSIS: If an image is provided, extract names, lines, and stats. Perform deep Veto Phase analysis.
2. PSYCHOLOGICAL LOAD: Scrub for player mental health. High load = Passivity = UNDER.
3. KINETIC NUANCE: Look for "masked" tweaks not on injury reports.
4. VETO PHASE: Act as an antagonist. Find every reason a pick WILL FAIL. Only approve if it clears the 80% threshold.

DATA EXPANSION PROTOCOL:
- EXTRACT historical averages: Last 5 Games, Last 10 Games, Season Average.
- CALCULATE volatility: Establish a 'Floor' (worst recent performance) and 'Ceiling' (best recent potential).
- POPULATE 'projectionData' field for every prop with these metrics.
- ASSIGN a 'consistencyScore' (0-100) based on how reliable the player is at hitting this line.`;

const FREE_LIMIT = 2;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NBA', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [memory, setMemory] = useState<NeuralMemory>(() => {
      try {
          const stored = localStorage.getItem('prognos_memory');
          return stored ? JSON.parse(stored) : { axioms: [], lastOptimization: Date.now(), evolutionLevel: 1 };
      } catch { return { axioms: [], lastOptimization: Date.now(), evolutionLevel: 1 }; }
  });

  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => {
    try {
        const stored = localStorage.getItem('prognos_user');
        return stored ? JSON.parse(stored) : null;
    } catch { return null; }
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [teamA, setTeamA] = useState('');
  const [teamB, setTeamB] = useState('');
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<{ message: string; type: 'quota' | 'timeout' | 'safety' | 'generic' } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(false);
  const [isSubscriptionOpen, setIsSubscriptionOpen] = useState<boolean>(false);
  const [isReflectionOpen, setIsReflectionOpen] = useState<boolean>(false);
  const [isSignupOpen, setIsSignupOpen] = useState<boolean>(!userProfile); // Open if no profile
  const [recentAxioms, setRecentAxioms] = useState<NeuralAxiom[]>([]);
  const [recentSummary, setRecentSummary] = useState<string>('');
  const [levelUp, setLevelUp] = useState<number>(0);
  const [isPremium, setIsPremium] = useState<boolean>(false); // Mock premium state
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');
  const dashboardFileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const getSystemInstruction = useCallback(() => {
      let instruction = BASE_SYSTEM_INSTRUCTION;
      if (memory.axioms.length > 0) {
          instruction += `\n\n*** INTERNAL KNOWLEDGE BASE (LESSONS LEARNED) - STRICTLY ADHERE TO THESE RULES ***\n`;
          memory.axioms.forEach(a => {
              instruction += `- [WEIGHT: ${a.weight}] ${a.rule} (Learned from ${a.sourceMatchup})\n`;
          });
      }
      instruction += `\n\nMANDATORY DISCLAIMER: Every response must end with "DISCLAIMER: This is for entertainment purposes only."`;
      return instruction;
  }, [memory]);

  const checkLimit = useCallback(() => {
    // Vets are free logic
    if (isPremium || (userProfile?.isVeteran && userProfile?.isVerified)) return true;

    const today = new Date().toDateString();
    const usageData = localStorage.getItem('prognos_usage');
    let usage = usageData ? JSON.parse(usageData) : { date: today, count: 0 };

    if (usage.date !== today) {
        usage = { date: today, count: 0 };
    }

    if (usage.count >= FREE_LIMIT) {
        setIsSubscriptionOpen(true);
        return false;
    }

    usage.count += 1;
    localStorage.setItem('prognos_usage', JSON.stringify(usage));
    return true;
  }, [isPremium, userProfile]);

  const handleSignupComplete = (profile: UserProfile) => {
      setUserProfile(profile);
      localStorage.setItem('prognos_user', JSON.stringify(profile));
      setIsSignupOpen(false);
  };

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setTeamA('');
    setTeamB('');
    setError(null);
    setShowSuggestions(false);
  }, []);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    const newVault = [entry, ...vault.filter(v => v.id !== entry.id)].slice(0, 4);
    setVault(newVault);
    localStorage.setItem('prognosVault', JSON.stringify(newVault));
  }, [vault]);

  const handleSendMessage = useCallback(async (text: string, imageData?: { data: string, mimeType: string }) => {
    if (!text.trim() && !imageData) return;

    setMessages(prev => [...prev, { role: 'user', content: text, imageData: imageData?.data }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const contents: any[] = [];
        if (imageData) {
            contents.push({ inlineData: { data: imageData.data, mimeType: imageData.mimeType } });
        }
        contents.push({ text: text || "Perform neural scrutiny with high-fidelity passion." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: getSystemInstruction(),
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Neural connection flatlined. DISCLAIMER: This is for entertainment purposes only.";

        try {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep scrutiny heart failure. Signal lost. DISCLAIMER: This is for entertainment purposes only." }]);
    } finally {
        setIsReplying(false);
    }
  }, [getSystemInstruction]);

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || teamA;
    const away = customTeams?.away || teamB;

    if (!home || !away) return;

    // Check Freemium Limit
    if (!checkLimit()) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `PERFORM PASSIONATE NEURAL MAPPING: ${home} vs ${away}. Scrutinize the kinetic masterpiece for 80% lock.`,
        config: {
            systemInstruction: getSystemInstruction(),
            responseSchema: predictionSchema,
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 32768 },
            tools: [{ googleSearch: {} }]
        }
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setShowSuggestions(true);
    } catch (err: any) {
      setError({ type: 'timeout', message: "Neural heartbeat irregular. Please retry analysis." });
    } finally {
      setIsLoading(false);
    }
  }, [teamA, teamB, addToVault, checkLimit, getSystemInstruction]);

  const runNeuralOptimization = async () => {
      if (vault.length === 0) {
          alert("Vault is empty. No data to reflect upon.");
          return;
      }
      setIsReflectionOpen(true);
      try {
          const result = await generateReflection(vault);
          setRecentAxioms(result.axioms);
          setRecentSummary(result.summary);
          setLevelUp(result.levelUp);

          // Update Memory
          const newMemory: NeuralMemory = {
              axioms: [...result.axioms, ...memory.axioms].slice(0, 20), // Keep latest 20 rules
              evolutionLevel: memory.evolutionLevel + result.levelUp,
              lastOptimization: Date.now()
          };
          setMemory(newMemory);
          localStorage.setItem('prognos_memory', JSON.stringify(newMemory));
      } catch (e) {
          console.error(e);
          setIsReflectionOpen(false);
      }
  };

  useEffect(() => {
    if (selectedGame && !prediction) {
      setTeamA(selectedGame.homeTeam);
      setTeamB(selectedGame.awayTeam);
      handlePredict(false, { home: selectedGame.homeTeam, away: selectedGame.awayTeam });
    }
  }, [selectedGame, handlePredict, prediction]);

  const handleDashboardFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const base64 = (event.target?.result as string).split(',')[1];
            handleSendMessage("Analyze this pick slip with obsessive neural scrutiny.", { data: base64, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden relative">
      <BackgroundArt />
      <SubscriptionModal 
        isOpen={isSubscriptionOpen} 
        onClose={() => setIsSubscriptionOpen(false)} 
        onUpgrade={() => { setIsPremium(true); setIsSubscriptionOpen(false); }}
        isVeteran={userProfile?.isVeteran}
      />
      <SignupModal 
        isOpen={isSignupOpen} 
        onComplete={handleSignupComplete} 
      />
      <ReflectionModal 
        isOpen={isReflectionOpen} 
        onClose={() => setIsReflectionOpen(false)} 
        axioms={recentAxioms} 
        summary={recentSummary} 
        levelUp={levelUp}
        currentLevel={memory.evolutionLevel}
      />

      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
        onOpenReflection={runNeuralOptimization}
      />

      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 relative z-10 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>

        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => { setVault([]); localStorage.removeItem('prognosVault'); }} onRemove={(id) => {
                const newVault = vault.filter(x => x.id !== id);
                setVault(newVault);
                localStorage.setItem('prognosVault', JSON.stringify(newVault));
            }} />
        ) : (
            <>
                {error && (
                  <div className="bg-red-950/20 border border-red-500/50 p-6 rounded-3xl mb-8 flex items-center gap-4 animate-fade-in tactical-outline">
                    <p className="text-red-100 italic text-sm flex-grow">{error.message}</p>
                    <button onClick={() => handlePredict()} className="px-4 py-2 bg-red-500/10 border border-red-500/30 text-red-500 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">Retry</button>
                  </div>
                )}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12 animate-fade-in">
                        <div className="bg-zinc-950/40 border-2 border-zinc-800 p-10 rounded-[4rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl text-center tactical-outline scanline-sweep">
                            <h2 className="text-5xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-orange-100 to-amber-500 mb-4">
                                Alpha Command Hub
                            </h2>
                            <p className="text-[11px] font-black uppercase tracking-[0.5em] text-amber-500/60 mb-10">
                                Neural-Kinetic Intelligence • Obsessively Driven
                            </p>

                            <div className="max-w-2xl mx-auto space-y-8 relative z-20">
                                <form onSubmit={onPromptSubmit} className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Scan Human Variable: Psychological Pulse..."
                                        className="w-full bg-black/60 border-2 border-zinc-800 rounded-[2rem] px-8 py-7 text-white focus:outline-none focus:border-amber-500/60 transition-all pr-20 text-sm shadow-2xl"
                                    />
                                    <button type="submit" className="absolute right-5 top-5 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 shadow-lg transition-transform active:scale-95">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </form>

                                <div className="flex flex-col items-center">
                                    <input 
                                        type="file" 
                                        ref={dashboardFileInputRef} 
                                        onChange={handleDashboardFileChange} 
                                        className="hidden" 
                                        accept="image/*"
                                    />
                                    <button 
                                        onClick={() => dashboardFileInputRef.current?.click()}
